<template>
  <aside class="current-intents" :class="{ open: drawerOpen }" aria-label="当前网络意图">
    <header class="panel-head"><div><span>CURRENT NETWORK INTENTS</span><h2>当前网络意图 <b>{{ effectiveCount }}</b></h2></div><button type="button" class="refresh" aria-label="刷新当前网络意图" @click="refresh">↻</button></header>
    <p v-if="error" class="refresh-error" role="status">{{ error }}</p><p v-else class="refresh-state">{{ loading ? '正在读取持久化状态…' : '已使用只读状态快照刷新' }}</p>
    <div v-if="!hasLoaded && loading" class="panel-loading" aria-label="正在加载">正在加载…</div>
    <div v-else-if="!items.length" class="empty-state">当前没有正在执行或持续生效的网络意图。<small>可在左侧输入自然语言创建新的网络意图。</small></div>
    <div v-else class="intent-groups"><section v-for="section in sections" :key="section.key" class="intent-group" :class="section.key"><button class="group-head" type="button" :aria-expanded="!collapsed[section.key]" @click="toggle(section.key)"><span>{{ section.label }}</span><b>{{ section.items.length }}</b><i>{{ collapsed[section.key] ? '+' : '−' }}</i></button><div v-if="!collapsed[section.key]" class="intent-card-list"><article v-for="item in section.items" :key="item.traffic_scope_key || item.intent_id" class="intent-card" :class="[item.display_tone, { 'conversational-waiting': item.card_subtype === 'CONVERSATIONAL_WAITING', 'current-actionable-failure': item.card_subtype === 'CURRENT_ACTIONABLE_FAILURE' }]">
      <template v-if="item.card_subtype === 'CONVERSATIONAL_WAITING'"><div class="card-status"><strong>需要补充信息</strong></div><p class="intent-summary">{{ item.original_text || item.user_summary }}</p><p class="waiting-copy">尚未形成网络策略</p><p class="next-action">等待你补充必要信息</p><footer><button type="button" @click="$emit('open-detail', item.intent_id)">继续补充</button></footer></template>
      <template v-else-if="item.card_subtype === 'CURRENT_ACTIONABLE_FAILURE'"><div class="card-status"><strong>当前意图未能生效</strong></div><p class="intent-summary">{{ item.service || item.service_id || '网络服务' }}</p><p class="intent-route">{{ item.source_label || item.source_endpoint || '未解析' }} <b>→</b> {{ item.destination_label || item.destination_endpoint || '未解析' }}</p><div class="intent-meta"><span>{{ requestedObjectiveText(item) }}</span></div><p class="failure-reason">原因：{{ item.attention_reason || '当前意图需要处理' }}</p><p class="network-not-executed">网络配置：未执行</p><p class="next-action">{{ item.next_action }}</p><footer><button type="button" @click="$emit('open-detail', item.intent_id)">查看详情</button><button v-if="item.withdrawable" type="button" class="withdraw" :disabled="withdrawing === withdrawKey(item)" @click="confirmItem = item">撤销意图</button></footer></template>
      <template v-else><div class="card-status"><strong>{{ withdrawing === item.effective_scope_id ? '正在撤销…' : statusLabel(item) }}</strong><small v-if="item.evidence_state === 'STALE'">证据待刷新</small><small v-else-if="item.assurance_state === 'SATISFIED'">SLA 已满足</small></div><p class="intent-summary">{{ item.user_summary }}</p><p class="intent-route">{{ item.source_label || item.source_endpoint || '未解析' }} <b>→</b> {{ item.destination_label || item.destination_endpoint || '未解析' }}</p><div class="intent-meta"><span>{{ item.service || item.service_id || '通用网络服务' }}</span><span>{{ objectiveText(item) }}</span><span v-if="item.policy_version">Policy v{{ item.policy_version }}</span></div><div v-if="item.latest_measurements?.observed !== undefined" class="measurement">当前：{{ formatNumber(item.latest_measurements.observed) }} {{ item.latest_measurements.unit || '' }}</div><div class="evidence-row" :aria-label="`数据面证据：${evidenceLabel(item.evidence_state)}`"><span>ONOS / P4Runtime / TC</span><b>{{ evidenceLabel(item.evidence_state) }}</b></div><p v-if="!item.projection_consistent" class="projection-warning" role="status">状态投影同步中</p><p class="next-action">{{ item.next_action }}</p><footer><button type="button" @click="$emit('open-detail', item.intent_id)">查看详情</button><button type="button" :disabled="!item.can_locate_topology" @click="$emit('locate-topology', item)">定位拓扑</button><button v-if="item.withdrawable" type="button" class="withdraw" :disabled="withdrawing === item.effective_scope_id" @click="confirmItem = item">撤销意图</button></footer></template>
    </article></div></section></div>
    <button class="mobile-handle" type="button" :aria-expanded="drawerOpen" @click="drawerOpen = !drawerOpen">当前意图 {{ effectiveCount }}</button>
    <div v-if="confirmItem" class="withdraw-modal" role="dialog" aria-modal="true"><div><h3>确认撤销意图</h3><p>{{ confirmItem.service }} · {{ confirmItem.source_label }} → {{ confirmItem.destination_label }}</p><p>{{ confirmItem.card_subtype === 'CURRENT_ACTIONABLE_FAILURE' ? requestedObjectiveText(confirmItem) : `${objectiveText(confirmItem)} · ${confirmItem.policy_id} v${confirmItem.policy_version}` }}</p><small>{{ confirmItem.card_subtype === 'CURRENT_ACTIONABLE_FAILURE' ? '该意图尚未执行网络配置；撤销后它将退出当前异常队列，历史记录仍会保留。' : '撤销后系统将停止执行该意图，并清理对应网络配置。历史记录仍会保留。' }}</small><footer><button @click="confirmItem = null">取消</button><button class="withdraw" @click="withdraw">确认撤销</button></footer></div></div>
  </aside>
</template>
<script setup>
import { computed, reactive, ref } from 'vue'
import { useCurrentIntents } from '../../composables/useCurrentIntents'
import { currentEffectiveCount, currentIntentGroups } from '../../utils/currentIntentPresentation'
import { withdrawEffectiveIntent, withdrawIntent } from '../../api/client'
defineEmits(['open-detail', 'locate-topology'])
const { snapshot, loading, error, hasLoaded, refresh } = useCurrentIntents(); const drawerOpen = ref(false); const collapsed = reactive({ processing: false, enforcing: false, attention: false })
const confirmItem = ref(null); const withdrawing = ref(''); const withdrawalError = ref('')
const panelGroups = computed(() => currentIntentGroups(snapshot.value)); const effectiveCount = computed(() => currentEffectiveCount(snapshot.value)); const items = computed(() => Object.values(panelGroups.value).flat()); const sections = computed(() => [{ key: 'attention', label: '异常与等待', items: panelGroups.value.attention || [] }, { key: 'processing', label: '执行中', items: panelGroups.value.processing || [] }, { key: 'enforcing', label: '生效中', items: panelGroups.value.enforcing || [] }])
function toggle(key) { collapsed[key] = !collapsed[key] }
function statusLabel(item) { return item.display_status || '状态投影待刷新' }
function formatNumber(value) { const number = Number(value); return Number.isFinite(number) ? new Intl.NumberFormat('zh-CN', { maximumFractionDigits: 2 }).format(number) : value }
function objectiveText(item) { const qos = item.effective_qos || {}; return qos.target_mbps !== null && qos.target_mbps !== undefined ? `目标：${formatNumber(qos.target_mbps)} Mbps` : '目标：待确认' }
function requestedObjectiveText(item) { const objective = item.requested_objectives?.[0] || {}; return objective.requested !== null && objective.requested !== undefined ? `目标：${objective.requested} ${objective.unit || ''}`.trim() : '目标：待确认' }
function evidenceLabel(state) { return ({ VERIFIED: '已验证', PARTIALLY_VERIFIED: '部分验证', STALE: '证据待刷新', DRIFTED: '漂移', UNKNOWN: '待验证' })[state] || '不可用' }
function withdrawKey(item) { return item.withdraw_kind === 'INTENT' ? item.intent_id : item.effective_scope_id }
async function withdraw() { const item = confirmItem.value; if (!item || withdrawing.value) return; withdrawing.value = withdrawKey(item); withdrawalError.value = ''; try { if (item.withdraw_kind === 'INTENT') await withdrawIntent(item.intent_id); else await withdrawEffectiveIntent(item); confirmItem.value = null; await refresh() } catch (error) { withdrawalError.value = error?.status === 409 ? '该意图状态已发生变化，请确认最新状态后重试。' : '意图撤销未完成，当前网络状态未确认，请查看详情。'; await refresh() } finally { withdrawing.value = '' } }
</script>
<style scoped>
.current-intents{min-width:0;height:100%;display:flex;flex-direction:column;padding:16px;border:1px solid rgba(186,230,253,.7);border-radius:22px;background:rgba(255,255,255,.78);box-shadow:0 18px 42px rgba(15,23,42,.07);overflow:hidden}.panel-head{display:flex;justify-content:space-between;gap:8px;align-items:start}.panel-head span{font:800 9px ui-monospace,monospace;letter-spacing:.12em;color:#2784bd}.panel-head h2{margin:5px 0 0;color:#17213b;font-size:16px}.panel-head h2 b{display:inline-grid;place-items:center;min-width:20px;height:20px;border-radius:99px;background:#e0f2fe;color:#0369a1;font-size:11px}.refresh{border:0;background:transparent;color:#2784bd;font-size:18px;cursor:pointer}.refresh-state,.refresh-error{margin:7px 0 10px;font-size:10px;color:#718096}.refresh-error,.projection-warning{padding:7px;border-radius:8px;background:#fff3d8;color:#a16207}.intent-groups{min-height:0;overflow:auto}.intent-group{border-top:1px solid #e6eef4}.group-head{width:100%;display:flex;align-items:center;gap:6px;padding:11px 0;border:0;background:transparent;color:#34445d;font-weight:850;cursor:pointer;text-align:left}.group-head b{display:grid;place-items:center;min-width:18px;border-radius:99px;background:#eef6fb;color:#2877aa;font-size:10px}.group-head i{margin-left:auto;font-style:normal}.intent-card-list{display:grid;gap:8px;padding-bottom:10px}.intent-card{padding:11px;border:1px solid #dbeaf4;border-radius:13px;background:rgba(248,252,255,.9)}.intent-card.active,.intent-card.success{border-left:3px solid #18a36f}.intent-card.degraded,.intent-card.warning,.conversational-waiting{border-left:3px solid #d88900}.intent-card.waiting_for_infrastructure{border-left:3px solid #e77d16}.intent-card.progress{border-left:3px solid #2784bd}.card-status{display:flex;justify-content:space-between;gap:6px;color:#067153;font-size:11px}.degraded .card-status,.waiting_for_infrastructure .card-status,.warning .card-status{color:#b35c06}.progress .card-status{color:#1d6fa5}.card-status small{font-size:9px}.intent-summary{margin:8px 0 6px;color:#253750;font-size:11px;font-weight:700;line-height:1.4}.intent-route,.intent-meta,.measurement,.evidence-row,.next-action,.waiting-copy{margin:5px 0;color:#64748b;font-size:9px}.waiting-copy{font-weight:700;font-size:10px}.intent-route b{color:#2995d4}.intent-meta,.evidence-row{display:flex;justify-content:space-between;gap:6px}.evidence-row b{color:#127456}.next-action{padding-top:5px;border-top:1px solid #e6eef4;color:#397092}.intent-card footer{display:flex;gap:6px;margin-top:8px}.intent-card footer button{flex:1;padding:6px;border:1px solid #cfe1ee;border-radius:7px;background:white;color:#2077a9;font-size:9px;font-weight:800;cursor:pointer}.intent-card footer button:disabled{cursor:not-allowed;opacity:.5}.empty-state,.panel-loading{padding:26px 8px;color:#64748b;text-align:center;font-size:12px}.empty-state small{display:block;margin-top:6px;font-size:10px}.mobile-handle{display:none}@media(max-width:980px){.current-intents{position:fixed;right:10px;top:72px;bottom:12px;z-index:30;width:min(340px,calc(100vw - 20px));transform:translateX(calc(100% + 24px));transition:transform .2s ease}.current-intents.open{transform:translateX(0)}.mobile-handle{display:block;position:fixed;right:0;top:145px;transform:translateX(-100%);border:0;border-radius:12px 0 0 12px;padding:10px 8px;background:#0ea5e9;color:white;font-weight:800;writing-mode:vertical-rl;cursor:pointer}.current-intents.open .mobile-handle{right:-42px;transform:none}}
</style>
